int getSum(int a, int b) {
    unsigned ua = a, ub = b;      // modular arithmetic, no UB
    while (ub != 0) {
        unsigned carry = (ua & ub) << 1;
        ua ^= ub;                 // sum without carry
        ub = carry;
    }
    return static_cast<int>(ua); // well-defined since C++20
}

def reverse_bits(n):
    res = 0
    for _ in range(32):          # exactly 32 bits, not bit_length()
        res = (res << 1) | (n & 1)
        n >>= 1
    return res

