int hammingWeight(uint32_t n) {
    int cnt = 0;
    while (n) {
        n &= n - 1;   // clear the lowest set bit
        ++cnt;
    }
    return cnt;
}

def count_bits(n):
    ans = [0] * (n + 1)
    for i in range(1, n + 1):
        # i & (i - 1) is i without its lowest set bit, already computed
        ans[i] = ans[i & (i - 1)] + 1
    return ans

