int minOperations(int n) {
    unsigned x = n;
    int ops = 0;
    while (x) {
        if ((x & 1u) == 0) { x >>= 1; continue; }
        if ((x & 3u) == 3u) x += 1;  // run of 1s: carry it upward
        else x -= 1;                  // isolated 1: remove it
        ++ops;
    }
    return ops;
}

