long long sumBitDifferences(const vector<int>& a) {
    long long n = a.size(), total = 0;
    for (int b = 0; b < 32; ++b) {
        long long ones = 0;
        for (int v : a)
            ones += (static_cast<uint32_t>(v) >> b) & 1u;
        total += 2 * ones * (n - ones);  // ordered pairs
