def add_binary(a, b):
    i, j, carry = len(a) - 1, len(b) - 1, 0
    out = []
    while i >= 0 or j >= 0 or carry:
        s = carry
        if i >= 0:
            s += a[i] == '1'
            i -= 1
        if j >= 0:
            s += b[j] == '1'
            j -= 1
        out.append('1' if s & 1 else '0')
        carry = s >> 1
    return ''.join(reversed(out))

int divide(int dividend, int divisor) {
    bool neg = (dividend < 0) != (divisor < 0);
    uint32_t a = dividend < 0 ? 0u - uint32_t(dividend) : dividend;
    uint32_t b = divisor < 0 ? 0u - uint32_t(divisor) : divisor;
    uint32_t q = 0;
    for (int i = 31; i >= 0; --i)
        if ((a >> i) >= b) {      // b << i fits and is <= a
            a -= b << i;
            q |= 1u << i;
        }
    if (!neg) return q > INT_MAX ? INT_MAX : int(q);
    return int(0u - q);           // q <= 2^31; C++20 modular
}

int numSteps(const string& s) {
    int steps = 0, carry = 0;
    for (int i = (int)s.size() - 1; i > 0; --i) {
        int bit = (s[i] - '0') + carry;
        if (bit == 1) { steps += 2; carry = 1; } // odd: +1, then /2
        else steps += 1;                         // even: just /2
