long long maxNumberOfFamilies(long long n,
                              const vector<vector<int>>& reserved) {
    unordered_map<int, int> rows;  // row -> mask of reserved seats 2..9
    for (auto& r : reserved)
        if (r[1] >= 2 && r[1] <= 9) rows[r[0]] |= 1 << r[1];
    const int L = 0b0000111100, M = 0b0011110000, R = 0b1111000000;
    long long total = 2 * (n - (long long)rows.size());
    for (auto& [row, m] : rows) {
        int c = !(m & L) + !(m & R);
        if (c == 0 && !(m & M)) c = 1;
        total += c;
    }
    return total;
}

