double myPow(double x, int n) {
  // long long: -n overflows int when n == INT_MIN
  long long e = n;
  if (e < 0) {
    x = 1.0 / x;
    e = -e;
  }
  double result = 1.0;
  while (e > 0) {                 // binary exponentiation: O(log |n|) multiplications
    if (e & 1) result *= x;       // this bit of the exponent is set
    x *= x;                       // x^(2^k) for the next bit
    e >>= 1;
  }
  return result;
}

#include <climits>

// Integer division without '*', '/' or '%', truncating toward zero; clamp overflow to INT_MAX.
int divide(int dividend, int divisor) {
  if (dividend == INT_MIN && divisor == -1) return INT_MAX;   // the only overflowing case
  // Work with negatives: |INT_MIN| does not fit in int, but every positive int fits as a negative.
  bool negative = (dividend < 0) != (divisor < 0);
  int a = dividend > 0 ? -dividend : dividend;
  int b = divisor > 0 ? -divisor : divisor;
  int quotient = 0;
  while (a <= b) {                    // |a| >= |b|
    int chunk = b, times = 1;
    // Double the chunk while it still fits in a, and doubling does not overflow.
    while (chunk >= INT_MIN / 2 && a <= chunk + chunk) {
      chunk += chunk;
      times += times;
    }
    a -= chunk;
    quotient += times;                // at most ~31 rounds of ~31 doublings: O(log^2)
  }
  return negative ? -quotient : quotient;
}

#include <vector>

// In place, O(1) extra memory: bit 0 = current state, bit 1 = next state.
void gameOfLife(std::vector<std::vector<int>>& b) {
  const int R = b.size(), C = R ? b[0].size() : 0;
  for (int r = 0; r < R; ++r)
    for (int c = 0; c < C; ++c) {
      int live = 0;
      for (int dr = -1; dr <= 1; ++dr)
        for (int dc = -1; dc <= 1; ++dc) {
          if (dr == 0 && dc == 0) continue;
          int nr = r + dr, nc = c + dc;
          if (nr >= 0 && nr < R && nc >= 0 && nc < C)
            live += b[nr][nc] & 1;            // read only the CURRENT state bit
        }
      bool alive = b[r][c] & 1;
      if (live == 3 || (alive && live == 2))  // survives with 2-3, born with exactly 3
        b[r][c] |= 2;
    }
  for (auto& row : b)
    for (int& cell : row) cell >>= 1;         // next state becomes the current state
}

