// מסכה לביטים lo..hi (כולל), 0 <= lo <= hi <= 31. 64 ביט כדי ש-hi - lo + 1 = 32 לא יהיה UB
uint32_t rangeMask(int lo, int hi) {
    return (uint32_t)(((1ull << (hi - lo + 1)) - 1) << lo);
}
uint32_t setRange(uint32_t x, int lo, int hi)    { return x | rangeMask(lo, hi); }
uint32_t clearRange(uint32_t x, int lo, int hi)  { return x & ~rangeMask(lo, hi); }
uint32_t toggleRange(uint32_t x, int lo, int hi) { return x ^ rangeMask(lo, hi); }

