// מינימום בלי אופרטורי השוואה. הפרש ב-64 ביט: אין overflow גם עבור INT_MIN ו-INT_MAX.
int minNoCmp(int a, int b) {
    long long d = (long long)a - b;
    long long mask = d >> 63;                          // -1 (כל הביטים) אם a < b, אחרת 0 (C++20: shift אריתמטי)
    return (int)(b + (d & mask));                      // a < b: b + (a - b) = a; אחרת b
}
int min3(int a, int b, int c) {
    return minNoCmp(minNoCmp(a, b), c);
}

