// החזקה הקטנה ביותר של 2 שגדולה או שווה ל-n. מחזיר 64 ביט כי עבור n > 2^31 התשובה 2^32.
uint64_t nextPow2(uint32_t n) {
    if (n <= 1) return 1;
    uint32_t v = n - 1;                                // חזקה של 2 תחזור לעצמה
    v |= v >> 1;                                       // "מורחים" את ה-MSB לכל הביטים שמתחתיו
    v |= v >> 2;
    v |= v >> 4;
    v |= v >> 8;
    v |= v >> 16;
    return (uint64_t)v + 1;                            // 0..01..1 + 1 = חזקה של 2
}

// nums: מספרים שונים זה מזה בטווח [0, limit). מיון בזיכרון של limit ביטים.
vector<uint32_t> bitmapSort(const vector<uint32_t>& nums, uint32_t limit) {
    vector<uint64_t> bits((limit + 63) / 64, 0);       // 10^7 ביטים = 1.25 MB
    for (uint32_t x : nums)
        bits[x >> 6] |= 1ull << (x & 63);              // מדליקים את הביט של x
    vector<uint32_t> out;
    out.reserve(nums.size());
    for (size_t w = 0; w < bits.size(); ++w)
        for (uint64_t word = bits[w]; word; word &= word - 1)   // רק ביטים דולקים
            out.push_back((uint32_t)(w * 64 + countr_zero(word)));
    return out;
}
